/* ─────────────────────────── 2. What a name may not be ─────────────────────────── */

/**
 * Why a name reads as a placeholder, a bot or staff, or NULL when it reads as a person's.
 * names.ts placeholderReason, step for step; the same cases run against both.
 */
CREATE OR REPLACE FUNCTION public.virtual_name_placeholder(_first text, _last text)
RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  f text := public.virtual_name_fold(_first);
  l text := public.virtual_name_fold(_last);
  v_full text;
  t text;
  k text;
BEGIN
  IF f = '' THEN RETURN 'Add a first name'; END IF;
  IF coalesce(_first, '') ~ '[0-9]' OR coalesce(_last, '') ~ '[0-9]' THEN RETURN 'Names with numbers read as placeholders'; END IF;
  v_full := CASE WHEN l = '' THEN f ELSE f || ' ' || l END;
  IF EXISTS (SELECT 1 FROM public.virtual_name_blocked b WHERE b.full_name = v_full AND b.kind = 'stock') THEN
    RETURN 'That''s a placeholder name';
  END IF;
  FOREACH t IN ARRAY string_to_array(v_full, ' ') LOOP
    SELECT w.kind INTO k FROM public.virtual_name_words w WHERE w.word = t;
    IF k = 'placeholder' THEN RETURN '"' || initcap(t) || '" reads as a placeholder'; END IF;
    IF k = 'bot' THEN RETURN '"' || initcap(t) || '" reads like a bot''s name'; END IF;
    IF k = 'staff' THEN RETURN '"' || initcap(t) || '" could be mistaken for JF Effect staff'; END IF;
    IF k = 'mash' OR t ~ '^(.)\1+$' THEN RETURN 'That doesn''t read like a real name'; END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM unnest(string_to_array(v_full, ' ')) x WHERE char_length(x) = 1) THEN
    RETURN 'Use a full first and last name, not initials';
  END IF;
  IF l <> '' AND replace(f, ' ', '') = replace(l, ' ', '') THEN RETURN 'First and last name are the same'; END IF;
  RETURN NULL;
END;
$$;
REVOKE ALL ON FUNCTION public.virtual_name_placeholder(text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_name_placeholder(text, text) TO service_role;

/** A username that reads as a placeholder, a bot or staff. names.ts usernameReadsAsPlaceholder. */
CREATE OR REPLACE FUNCTION public.virtual_username_placeholder(_username text)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  parts text[] := ARRAY(SELECT p FROM unnest(regexp_split_to_array(lower(coalesce(_username, '')), '[._0-9]+')) p WHERE p <> '');
BEGIN
  IF cardinality(parts) = 0 THEN RETURN true; END IF;
  IF EXISTS (SELECT 1 FROM public.virtual_name_blocked b WHERE b.kind = 'stock' AND b.full_name = array_to_string(parts, ' ')) THEN
    RETURN true;
  END IF;
  RETURN EXISTS (SELECT 1 FROM unnest(parts) p
                  WHERE EXISTS (SELECT 1 FROM public.virtual_name_words w WHERE w.word = p)
                     OR p ~ '^(.)\1+$'
                     OR p ~ '^(testuser|user|test|bot|demo)');
END;
$$;
REVOKE ALL ON FUNCTION public.virtual_username_placeholder(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_username_placeholder(text) TO service_role;

/**
 * Every real person's names, folded: the names they show in the Crew (preferred, first, the
 * first word of their name), their surname and their full name. Clients (every record), every
 * login that isn't a virtual account, and the coaches. Server only.
 */
CREATE OR REPLACE FUNCTION public.virtual_name_real_people()
RETURNS TABLE (first_f text, last_f text, full_f text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  WITH raw AS (
    SELECT c.first_name AS f, c.last_name AS l FROM public.clients c
    UNION ALL SELECT c.preferred_name, c.last_name FROM public.clients c WHERE nullif(btrim(c.preferred_name), '') IS NOT NULL
    UNION ALL SELECT split_part(btrim(c.full_name), ' ', 1), nullif(btrim(substr(btrim(c.full_name), strpos(btrim(c.full_name) || ' ', ' '))), '')
      FROM public.clients c WHERE nullif(btrim(c.full_name), '') IS NOT NULL
    UNION ALL SELECT split_part(btrim(p.full_name), ' ', 1), nullif(btrim(substr(btrim(p.full_name), strpos(btrim(p.full_name) || ' ', ' '))), '')
      FROM public.profiles p
     WHERE nullif(btrim(p.full_name), '') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.virtual_accounts v WHERE v.user_id = p.id)
    UNION ALL SELECT co.first_name, co.last_name FROM public.coaches co
    UNION ALL SELECT split_part(btrim(co.full_name), ' ', 1), nullif(btrim(substr(btrim(co.full_name), strpos(btrim(co.full_name) || ' ', ' '))), '')
      FROM public.coaches co WHERE nullif(btrim(co.full_name), '') IS NOT NULL
  ), folded AS (
    SELECT split_part(public.virtual_name_fold(r.f), ' ', 1) AS first_f, public.virtual_name_fold(r.l) AS last_f FROM raw r
  )
  SELECT DISTINCT x.first_f, x.last_f, btrim(x.first_f || ' ' || x.last_f)
    FROM folded x
   WHERE x.first_f <> '' OR x.last_f <> ''
$$;
REVOKE ALL ON FUNCTION public.virtual_name_real_people() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_name_real_people() TO service_role;

/** The gender a first name is used for in the pool: 'f', 'm', 'u' when it's both, NULL when unknown. */
CREATE OR REPLACE FUNCTION public.virtual_name_gender_of(_first text)
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT CASE WHEN count(DISTINCT gender) = 1 THEN min(gender)
              WHEN count(*) > 0 THEN 'u' END
    FROM public.virtual_name_firsts
   WHERE folded = split_part(public.virtual_name_fold(_first), ' ', 1)
$$;
REVOKE ALL ON FUNCTION public.virtual_name_gender_of(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_name_gender_of(text) TO service_role;

/** The origin a surname comes from in the pool (the first part of a double surname), NULL when unknown. */
CREATE OR REPLACE FUNCTION public.virtual_name_origin_of(_last text)
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT l.origin FROM public.virtual_name_lasts l JOIN public.virtual_name_origins o ON o.origin = l.origin
   WHERE l.folded = public.virtual_name_fold(split_part(coalesce(_last, ''), '-', 1))
   ORDER BY o.weight DESC, l.origin
   LIMIT 1
$$;
REVOKE ALL ON FUNCTION public.virtual_name_origin_of(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_name_origin_of(text) TO service_role;

/**
 * What's wrong with a name an admin typed for a virtual account (_uid: the account being renamed,
 * NULL for a new one), or NULL when it's fine: a placeholder, no surname, more than one word for
 * the first name (the Crew shows the first word), too long, a well-known person's, a real
 * member's full name or the first name a real member goes by, or the first name or surname of
 * another virtual account.
 */
CREATE OR REPLACE FUNCTION public.virtual_name_problem(_first text, _last text, _uid uuid DEFAULT NULL)
RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  p text := public.virtual_name_placeholder(_first, _last);
  f text := public.virtual_name_fold(_first);
  l text := public.virtual_name_fold(_last);
BEGIN
  IF p IS NOT NULL THEN RETURN p; END IF;
  IF l = '' THEN RETURN 'Add a last name'; END IF;
  IF btrim(_first) ~ '\s' THEN RETURN 'Use one word for the first name: the Crew shows the first word'; END IF;
  IF char_length(btrim(_first)) > 40 OR char_length(btrim(_last)) > 40 THEN RETURN 'Keep each name under 40 characters'; END IF;
  IF EXISTS (SELECT 1 FROM public.virtual_name_blocked b WHERE b.kind = 'well_known' AND b.full_name = f || ' ' || l) THEN
    RETURN 'That''s a well-known person''s name';
  END IF;
  IF EXISTS (SELECT 1 FROM public.virtual_name_real_people() r WHERE r.full_f = f || ' ' || l) THEN
    RETURN 'A member already has that name';
  END IF;
  IF EXISTS (SELECT 1 FROM public.virtual_name_real_people() r WHERE r.first_f = split_part(f, ' ', 1)) THEN
    RETURN 'A member goes by ' || btrim(_first) || ' in the Crew. Pick another first name so nobody mistakes one for the other';
  END IF;
  IF EXISTS (SELECT 1 FROM public.virtual_accounts v
              WHERE v.user_id IS DISTINCT FROM _uid AND split_part(public.virtual_name_fold(v.first_name), ' ', 1) = split_part(f, ' ', 1)) THEN
    RETURN 'Another virtual account is already called ' || btrim(_first);
  END IF;
  IF EXISTS (SELECT 1 FROM public.virtual_accounts v
              WHERE v.user_id IS DISTINCT FROM _uid AND v.last_name IS NOT NULL AND public.virtual_name_fold(v.last_name) = l) THEN
    RETURN 'Another virtual account already has the surname ' || btrim(_last);
  END IF;
  RETURN NULL;
END;
$$;
REVOKE ALL ON FUNCTION public.virtual_name_problem(text, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_name_problem(text, text, uuid) TO service_role;

/* ─────────────────────────── 3. Usernames ─────────────────────────── */

/** Whether a username is well formed, free (but for _exclude's own) and not one of _avoid. */
CREATE OR REPLACE FUNCTION public.virtual_username_free(_u text, _avoid text[] DEFAULT '{}', _exclude uuid DEFAULT NULL)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT _u ~ '^[a-z0-9._]{3,24}$' AND _u !~ '^[._]|[._]$|[._][._]'
     AND NOT (_u = ANY(coalesce(_avoid, '{}')))
     AND NOT public.virtual_username_placeholder(_u)
     AND NOT EXISTS (SELECT 1 FROM public.community_profiles cp WHERE cp.username = _u AND cp.user_id IS DISTINCT FROM _exclude)
     AND NOT EXISTS (SELECT 1 FROM public.virtual_accounts va WHERE va.slug = _u AND va.user_id IS DISTINCT FROM _exclude)
$$;
REVOKE ALL ON FUNCTION public.virtual_username_free(text, text[], uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_username_free(text, text[], uuid) TO service_role;

/**
 * A username made from the name the way people make theirs (ethan.mitchell, ethanmitchell,
 * ethan_mitchell, ethan.lifts, emitchell, mitchell.ethan, ethan.mitchell27), the first free one
 * in a shuffled order; NULL when the name has nothing to make one from.
 */
CREATE OR REPLACE FUNCTION public.virtual_username_for(_first text, _last text, _avoid text[] DEFAULT '{}', _exclude uuid DEFAULT NULL)
RETURNS text LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  f text := replace(public.virtual_name_fold(_first), ' ', '');
  l text := replace(public.virtual_name_fold(_last), ' ', '');
  w text := (ARRAY['lifts', 'trains', 'squats', 'pulls', 'benches', 'reps', 'moves', 'lifting', 'training']::text[])[1 + floor(random() * 9)::int];
  c text;
  n int;
BEGIN
  IF f = '' OR l = '' THEN RETURN NULL; END IF;
  f := left(f, 14);
  l := left(l, 16);
  FOR c IN
    SELECT x.u FROM (VALUES
      (f || '.' || l, 4.0), (f || l, 3.0), (f || '_' || l, 1.5), (f || '.' || w, 2.0),
      (left(f, 1) || l, 1.0), (l || '.' || f, 0.8),
      (f || '.' || l || (10 + floor(random() * 90))::int, 0.4), (f || l || (10 + floor(random() * 90))::int, 0.2)
    ) AS x(u, wt)
    ORDER BY -ln(1.0 - random()) / x.wt
  LOOP
    c := regexp_replace(left(c, 24), '[._]+$', '');
    IF public.virtual_username_free(c, _avoid, _exclude) THEN RETURN c; END IF;
  END LOOP;
  FOR n IN 2..99 LOOP
    c := left(f || '.' || l, 21) || n;
    IF public.virtual_username_free(c, _avoid, _exclude) THEN RETURN c; END IF;
  END LOOP;
  RETURN NULL;
END;
$$;
REVOKE ALL ON FUNCTION public.virtual_username_for(text, text, text[], uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_username_for(text, text, text[], uuid) TO service_role;

/* ─────────────────────────── 4. The generator ─────────────────────────── */

/**
 * Up to 12 natural names nobody has, each with its gender ('f' or 'm', the person's, whatever
 * the first name), origin and a free username. _gender NULL picks whichever the virtual accounts
 * have fewer of; _exclude is the account being renamed (its own name doesn't count as taken).
 * Strict first; after 300 tries for one name it lets go of the initials and real surnames rules,
 * never the rest.
 */
CREATE OR REPLACE FUNCTION public.virtual_name_generate(_count integer DEFAULT 5, _gender text DEFAULT NULL, _exclude uuid DEFAULT NULL)
RETURNS TABLE (first_name text, last_name text, gender text, origin text, username text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_n integer := least(greatest(coalesce(_count, 1), 1), 12);
  v_real_first text[];
  v_real_last text[];
  v_real_full text[];
  v_used_first text[];
  v_used_last text[];
  v_used_initials text[];
  v_used_users text[] := '{}';
  v_origin_count jsonb;
  v_f integer;
  v_m integer;
  v_g text;
  v_origin text;
  v_pairs jsonb;
  v_style text;
  v_first text;
  v_last text;
  v_second text;
  v_ff text;
  v_lf text;
  v_parts text[];
  v_user text;
  v_ok boolean;
  v_strict boolean;
  i integer;
  a integer;
BEGIN
  SELECT coalesce(array_agg(DISTINCT r.first_f) FILTER (WHERE r.first_f <> ''), '{}'),
         coalesce(array_agg(DISTINCT r.last_f) FILTER (WHERE r.last_f <> ''), '{}'),
         coalesce(array_agg(DISTINCT r.full_f), '{}')
    INTO v_real_first, v_real_last, v_real_full
    FROM public.virtual_name_real_people() r;
  SELECT coalesce(array_agg(split_part(public.virtual_name_fold(v.first_name), ' ', 1)), '{}'),
         coalesce(array_agg(public.virtual_name_fold(v.last_name)) FILTER (WHERE v.last_name IS NOT NULL), '{}'),
         coalesce(array_agg(left(public.virtual_name_fold(v.first_name), 1) || left(public.virtual_name_fold(v.last_name), 1)), '{}'),
         count(*) FILTER (WHERE v.name_gender = 'f'), count(*) FILTER (WHERE v.name_gender = 'm')
    INTO v_used_first, v_used_last, v_used_initials, v_f, v_m
    FROM public.virtual_accounts v
   WHERE v.user_id IS DISTINCT FROM _exclude;
  SELECT coalesce(jsonb_object_agg(x.o, x.n), '{}'::jsonb) INTO v_origin_count
    FROM (SELECT v.name_origin AS o, count(*) AS n FROM public.virtual_accounts v
           WHERE v.user_id IS DISTINCT FROM _exclude AND v.name_origin IS NOT NULL GROUP BY v.name_origin) x;

  FOR i IN 1..v_n LOOP
    v_g := CASE WHEN _gender IN ('f', 'm') THEN _gender
                WHEN v_f < v_m THEN 'f' WHEN v_m < v_f THEN 'm'
                WHEN random() < 0.5 THEN 'f' ELSE 'm' END;
    v_ok := false;
    FOR a IN 1..400 LOOP
      v_strict := a <= 300;
      SELECT o.origin, o.pairs INTO v_origin, v_pairs
        FROM public.virtual_name_origins o
       ORDER BY -ln(1.0 - random()) / (o.weight / (1.0 + 1.5 * coalesce((v_origin_count ->> o.origin)::numeric, 0)))
       LIMIT 1;
      SELECT l.name INTO v_last FROM public.virtual_name_lasts l
       WHERE l.origin = v_origin AND (l.only_gender IS NULL OR l.only_gender = v_g)
       ORDER BY random() LIMIT 1;
      CONTINUE WHEN v_last IS NULL;
      -- Now and then a double surname where families commonly carry two (Gagnon-Tremblay,
      -- Torres-Medina, Silva-Pereira): both from the same origin, never a made-up mix.
      IF v_origin IN ('french', 'hispanic', 'portuguese') AND random() < 0.06 AND v_last !~ '[ -]' THEN
        SELECT l.name INTO v_second FROM public.virtual_name_lasts l
         WHERE l.origin = v_origin AND l.name !~ '[ -]' AND l.only_gender IS NULL AND l.name <> v_last
         ORDER BY random() LIMIT 1;
        IF v_second IS NOT NULL AND char_length(v_last || '-' || v_second) <= 26 THEN v_last := v_last || '-' || v_second; END IF;
      END IF;
      SELECT p.key INTO v_style FROM jsonb_each_text(v_pairs) p
       ORDER BY -ln(1.0 - random()) / greatest(p.value::numeric, 0.0001) LIMIT 1;
      SELECT f.name INTO v_first FROM public.virtual_name_firsts f
       WHERE f.style = v_style AND (f.gender = v_g OR f.gender = 'u')
       ORDER BY -ln(1.0 - random()) / CASE WHEN f.gender = 'u' THEN 0.4 ELSE 1.0 END
       LIMIT 1;
      CONTINUE WHEN v_first IS NULL;
      v_ff := public.virtual_name_fold(v_first);
      v_lf := public.virtual_name_fold(v_last);
      -- a double surname's parts count one by one (Gagnon-Tremblay is a Gagnon and a Tremblay)
      v_parts := ARRAY(SELECT public.virtual_name_fold(x) FROM unnest(string_to_array(v_last, '-')) x);
      CONTINUE WHEN left(v_ff, 1) = left(v_lf, 1);
      CONTINUE WHEN split_part(v_ff, ' ', 1) = ANY(v_used_first) OR split_part(v_ff, ' ', 1) = ANY(v_real_first);
      CONTINUE WHEN v_lf = ANY(v_used_last) OR v_parts && v_used_last
                 OR (v_strict AND (v_lf = ANY(v_real_last) OR v_parts && v_real_last));
      CONTINUE WHEN (v_ff || ' ' || v_lf) = ANY(v_real_full);
      CONTINUE WHEN v_strict AND (left(v_ff, 1) || left(v_lf, 1)) = ANY(v_used_initials);
      CONTINUE WHEN EXISTS (SELECT 1 FROM public.virtual_name_blocked b WHERE b.full_name = v_ff || ' ' || v_lf);
      CONTINUE WHEN public.virtual_name_placeholder(v_first, v_last) IS NOT NULL;
      v_user := public.virtual_username_for(v_first, v_last, v_used_users, _exclude);
      CONTINUE WHEN v_user IS NULL;
      v_ok := true;
      EXIT;
    END LOOP;
    CONTINUE WHEN NOT v_ok;
    v_used_first := v_used_first || split_part(v_ff, ' ', 1);
    v_used_last := v_used_last || v_lf || v_parts;
    v_used_initials := v_used_initials || (left(v_ff, 1) || left(v_lf, 1));
    v_used_users := v_used_users || v_user;
    v_origin_count := jsonb_set(v_origin_count, ARRAY[v_origin], to_jsonb(coalesce((v_origin_count ->> v_origin)::int, 0) + 1));
    IF v_g = 'f' THEN v_f := v_f + 1; ELSE v_m := v_m + 1; END IF;
    first_name := v_first;
    last_name := v_last;
    gender := v_g;
    origin := v_origin;
    username := v_user;
    RETURN NEXT;
  END LOOP;
END;
$$;
REVOKE ALL ON FUNCTION public.virtual_name_generate(integer, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_name_generate(integer, text, uuid) TO service_role;

/* ─────────────────────────── 5. Naming an account ─────────────────────────── */

/**
 * Give a virtual account its name everywhere it's kept (the account, its profile, its login's
 * name) and, when asked, a new username and slug, keeping its id and everything it has. One
 * 'renamed' line in its activity with before and after. Server only: the admin functions and the
 * correction check before they call it.
 */
CREATE OR REPLACE FUNCTION public._virtual_apply_name(
  _uid uuid, _first text, _last text, _gender text, _origin text, _source text,
  _username text DEFAULT NULL, _slug text DEFAULT NULL, _actor uuid DEFAULT NULL, _detail jsonb DEFAULT '{}'::jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  va public.virtual_accounts;
  v_old_user text;
  v_full text := btrim(btrim(_first) || ' ' || coalesce(btrim(_last), ''));
BEGIN
  SELECT * INTO va FROM public.virtual_accounts WHERE user_id = _uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Not a virtual account' USING ERRCODE = '22023'; END IF;
  SELECT cp.username INTO v_old_user FROM public.community_profiles cp WHERE cp.user_id = _uid;
  UPDATE public.virtual_accounts SET
    first_name = btrim(_first),
    last_name = nullif(btrim(coalesce(_last, '')), ''),
    name_gender = CASE WHEN _gender IN ('f', 'm', 'u') THEN _gender ELSE public.virtual_name_gender_of(_first) END,
    name_origin = coalesce(_origin, public.virtual_name_origin_of(_last)),
    name_source = _source,
    name_set_at = now(),
    slug = coalesce(_slug, slug),
    updated_by = coalesce(_actor, updated_by),
    updated_at = now()
  WHERE user_id = _uid;
  UPDATE public.profiles SET full_name = v_full WHERE id = _uid;
  UPDATE auth.users
     SET raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) || jsonb_build_object('full_name', v_full),
         email = CASE WHEN _slug IS NOT NULL THEN _slug || '@virtual.jfeffect.invalid' ELSE email END,
         updated_at = now()
   WHERE id = _uid;
  IF _slug IS NOT NULL THEN
    UPDATE auth.identities
       SET identity_data = coalesce(identity_data, '{}'::jsonb) || jsonb_build_object('email', _slug || '@virtual.jfeffect.invalid'),
           updated_at = now()
     WHERE user_id = _uid AND provider = 'email';
  END IF;
  IF _username IS NOT NULL AND _username IS DISTINCT FROM v_old_user THEN
    UPDATE public.community_profiles SET username = _username, username_set_at = now(), avatar_path = NULL, updated_at = now()
     WHERE user_id = _uid;
  END IF;
  INSERT INTO public.virtual_account_activity (user_id, action, actor_user_id, detail)
  VALUES (_uid, 'renamed', _actor,
          coalesce(_detail, '{}'::jsonb) || jsonb_build_object(
            'source', _source,
            'before', jsonb_build_object('first_name', va.first_name, 'last_name', va.last_name, 'username', v_old_user),
            'after', jsonb_build_object('first_name', btrim(_first), 'last_name', nullif(btrim(coalesce(_last, '')), ''),
                                        'username', coalesce(_username, v_old_user))));
END;
$$;
REVOKE ALL ON FUNCTION public._virtual_apply_name(uuid, text, text, text, text, text, text, text, uuid, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public._virtual_apply_name(uuid, text, text, text, text, text, text, text, uuid, jsonb) TO service_role;

/** Never a placeholder name on a virtual account, whatever writes it. */
CREATE OR REPLACE FUNCTION public.tg_virtual_accounts_name_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  r text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.first_name IS NOT DISTINCT FROM OLD.first_name AND NEW.last_name IS NOT DISTINCT FROM OLD.last_name THEN
    RETURN NEW;
  END IF;
  r := public.virtual_name_placeholder(NEW.first_name, NEW.last_name);
  IF r IS NOT NULL THEN RAISE EXCEPTION '%', r USING ERRCODE = '22023'; END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS virtual_accounts_name_guard ON public.virtual_accounts;
CREATE TRIGGER virtual_accounts_name_guard BEFORE INSERT OR UPDATE OF first_name, last_name ON public.virtual_accounts
  FOR EACH ROW EXECUTE FUNCTION public.tg_virtual_accounts_name_guard();

/**
 * Rename a virtual account to a name an admin typed or picked from the suggestions, checked like
 * any (virtual_name_problem), and optionally give it a new username. Admins only.
 */
CREATE OR REPLACE FUNCTION public.admin_virtual_account_rename(
  _uid uuid, _first text, _last text, _username text DEFAULT NULL, _gender text DEFAULT NULL,
  _origin text DEFAULT NULL, _source text DEFAULT 'admin')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_problem text;
  v_user text := nullif(lower(btrim(coalesce(_username, ''))), '');
  v_old_user text;
  va public.virtual_accounts;
BEGIN
  IF NOT public.has_role(v_actor, 'admin') THEN RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.virtual_accounts WHERE user_id = _uid) THEN
    RAISE EXCEPTION 'Not a virtual account' USING ERRCODE = '22023';
  END IF;
  v_problem := public.virtual_name_problem(_first, _last, _uid);
  IF v_problem IS NOT NULL THEN RAISE EXCEPTION '%', v_problem USING ERRCODE = '22023'; END IF;
  SELECT cp.username INTO v_old_user FROM public.community_profiles cp WHERE cp.user_id = _uid;
  IF v_user IS NOT NULL AND v_user IS DISTINCT FROM v_old_user AND NOT public.virtual_username_free(v_user, '{}', _uid) THEN
    RAISE EXCEPTION 'That username is taken or doesn''t read like a person''s' USING ERRCODE = '23505';
  END IF;
  PERFORM public._virtual_apply_name(_uid, _first, _last, _gender, nullif(_origin, ''),
                                     CASE WHEN _source = 'generated' THEN 'generated' ELSE 'admin' END,
                                     v_user, NULL, v_actor, '{}'::jsonb);
  SELECT * INTO va FROM public.virtual_accounts WHERE user_id = _uid;
  RETURN to_jsonb(va);
END;
$$;
REVOKE ALL ON FUNCTION public.admin_virtual_account_rename(uuid, text, text, text, text, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_virtual_account_rename(uuid, text, text, text, text, text, text) TO authenticated;

/** Fresh names for the admin page: for a new account, or to rename _uid (its own name isn't taken). */
CREATE OR REPLACE FUNCTION public.admin_virtual_name_suggestions(_count integer DEFAULT 3, _gender text DEFAULT NULL, _uid uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO 'public' AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501'; END IF;
  RETURN (SELECT coalesce(jsonb_agg(to_jsonb(g)), '[]'::jsonb) FROM public.virtual_name_generate(_count, _gender, _uid) g);
END;
$$;
REVOKE ALL ON FUNCTION public.admin_virtual_name_suggestions(integer, text, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_virtual_name_suggestions(integer, text, uuid) TO authenticated;

/** The admin page's check as a name is typed: what's wrong with it, and a free username for it. */
CREATE OR REPLACE FUNCTION public.admin_virtual_name_check(_first text, _last text, _uid uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_problem text;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501'; END IF;
  v_problem := public.virtual_name_problem(_first, _last, _uid);
  RETURN jsonb_build_object(
    'problem', v_problem,
    'username', CASE WHEN v_problem IS NULL THEN public.virtual_username_for(_first, _last, '{}', _uid) END,
    'gender', public.virtual_name_gender_of(_first),
    'origin', public.virtual_name_origin_of(_last));
END;
$$;
REVOKE ALL ON FUNCTION public.admin_virtual_name_check(text, text, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_virtual_name_check(text, text, uuid) TO authenticated;

/**
 * Rename every virtual account whose name reads as a placeholder to a generated one of the same
 * gender when that's known, keeping its id, likes, followers and history. A username or slug that
 * reads as a placeholder, or carries the old first name, is replaced with the new name's. Returns
 * how many were renamed. Run here, and on every like tick so nothing waits for an admin.
 */
CREATE OR REPLACE FUNCTION public.virtual_accounts_fix_placeholder_names()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  va record;
  c record;
  v_user text;
  v_reason text;
  v_old_first text;
  v_g text;
  v_n integer := 0;
BEGIN
  FOR va IN
    SELECT v.*, cp.username AS username FROM public.virtual_accounts v
      LEFT JOIN public.community_profiles cp ON cp.user_id = v.user_id
     WHERE public.virtual_name_placeholder(v.first_name, v.last_name) IS NOT NULL
     ORDER BY v.created_at
  LOOP
    v_reason := public.virtual_name_placeholder(va.first_name, va.last_name);
    v_g := CASE WHEN va.name_gender IN ('f', 'm') THEN va.name_gender
                WHEN public.virtual_name_gender_of(va.first_name) IN ('f', 'm') THEN public.virtual_name_gender_of(va.first_name)
                WHEN public.virtual_name_fold(va.first_name) IN ('jane', 'mary', 'baby jane') THEN 'f'
                WHEN public.virtual_name_fold(va.first_name) IN ('john', 'jon', 'joe', 'richard', 'fred') THEN 'm' END;
    SELECT * INTO c FROM public.virtual_name_generate(1, v_g, va.user_id) LIMIT 1;
    CONTINUE WHEN NOT FOUND;
    v_old_first := replace(public.virtual_name_fold(va.first_name), ' ', '');
    v_user := CASE WHEN va.username IS NULL OR public.virtual_username_placeholder(va.username)
                        OR (char_length(v_old_first) >= 3 AND position(v_old_first IN va.username) > 0)
                   THEN c.username END;
    PERFORM public._virtual_apply_name(
      va.user_id, c.first_name, c.last_name, c.gender, c.origin, 'corrected', v_user,
      CASE WHEN public.virtual_username_placeholder(va.slug) OR (char_length(v_old_first) >= 3 AND position(v_old_first IN va.slug) > 0)
           THEN coalesce(v_user, c.username) END,
      NULL, jsonb_build_object('by', 'automatic', 'reason', v_reason));
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END;
$$;
REVOKE ALL ON FUNCTION public.virtual_accounts_fix_placeholder_names() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_accounts_fix_placeholder_names() TO service_role;

/* ─────────────────────────── 6. Creating and changing accounts ─────────────────────────── */

DROP FUNCTION IF EXISTS public.admin_virtual_account_create(text, text, text, text, text, text[]);

/**
 * Create one virtual account: a login nobody can sign in to (banned, a random password, an
 * address on .invalid), a Crew profile with a username and bio, no photo, no media of any kind,
 * no athlete record, no membership row, no subscription. Its name is checked like any
 * (virtual_name_problem). Admins only (or the server).
 */
CREATE OR REPLACE FUNCTION public.admin_virtual_account_create(
  _slug text, _first text, _last text, _bio text, _background text DEFAULT NULL, _disciplines text[] DEFAULT '{}',
  _name_source text DEFAULT 'admin', _name_gender text DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_id uuid := gen_random_uuid();
  v_slug text := lower(btrim(coalesce(_slug, '')));
  v_email text;
  v_full text := btrim(btrim(coalesce(_first, '')) || ' ' || btrim(coalesce(_last, '')));
  v_problem text;
BEGIN
  IF v_actor IS NOT NULL AND NOT public.has_role(v_actor, 'admin') THEN
    RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501';
  END IF;
  v_problem := public.virtual_name_problem(_first, _last, NULL);
  IF v_problem IS NOT NULL THEN RAISE EXCEPTION '%', v_problem USING ERRCODE = '22023'; END IF;
  IF v_slug !~ '^[a-z0-9._]{3,24}$' OR v_slug ~ '^[._]|[._]$|\.\.' THEN
    RAISE EXCEPTION 'Usernames are 3 to 24 letters, numbers, dots or underscores' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.community_profiles cp WHERE cp.username = v_slug)
     OR EXISTS (SELECT 1 FROM public.virtual_accounts va WHERE va.slug = v_slug) THEN
    RAISE EXCEPTION 'That username is taken' USING ERRCODE = '23505';
  END IF;
  IF public.virtual_username_placeholder(v_slug) THEN
    RAISE EXCEPTION 'That username doesn''t read like a person''s' USING ERRCODE = '22023';
  END IF;
  v_email := v_slug || '@virtual.jfeffect.invalid';
  INSERT INTO auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
                          raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
                          confirmation_token, recovery_token, email_change_token_new, email_change,
                          email_change_token_current, phone_change, phone_change_token, reauthentication_token,
                          banned_until, is_sso_user, is_anonymous)
  VALUES ('00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated', v_email,
          extensions.crypt(gen_random_uuid()::text || clock_timestamp()::text, extensions.gen_salt('bf')), now(),
          jsonb_build_object('provider', 'email', 'providers', jsonb_build_array('email'), 'jf_virtual', true),
          jsonb_build_object('full_name', v_full, 'jf_virtual', true), now(), now(),
          '', '', '', '', '', '', '', '', now() + interval '100 years', false, false);
  INSERT INTO auth.identities (provider_id, user_id, identity_data, provider, created_at, updated_at)
  VALUES (v_id::text, v_id, jsonb_build_object('sub', v_id::text, 'email', v_email, 'email_verified', true), 'email', now(), now());
  INSERT INTO public.virtual_accounts (user_id, slug, first_name, last_name, background, created_by, updated_by,
                                       name_gender, name_origin, name_source, name_set_at)
  VALUES (v_id, v_slug, btrim(_first), nullif(btrim(coalesce(_last, '')), ''), nullif(btrim(coalesce(_background, '')), ''), v_actor, v_actor,
          CASE WHEN _name_gender IN ('f', 'm', 'u') THEN _name_gender ELSE public.virtual_name_gender_of(_first) END,
          public.virtual_name_origin_of(_last),
          CASE WHEN _name_source IN ('starter', 'generated', 'admin') THEN _name_source ELSE 'admin' END, now());
  INSERT INTO public.community_profiles (user_id, username, username_set_at, bio, disciplines, discoverable)
  VALUES (v_id, v_slug, now(), nullif(left(btrim(coalesce(_bio, '')), 150), ''),
          coalesce(ARRAY(SELECT d FROM unnest(coalesce(_disciplines, '{}')) d
                          WHERE d IN ('powerlifting', 'bodybuilding', 'strength', 'glutes', 'fitness') LIMIT 3), '{}'), false)
  ON CONFLICT (user_id) DO UPDATE
     SET username = EXCLUDED.username, username_set_at = EXCLUDED.username_set_at, bio = EXCLUDED.bio,
         disciplines = EXCLUDED.disciplines, discoverable = false, avatar_path = NULL;
  INSERT INTO public.virtual_account_activity (user_id, action, actor_user_id, detail)
  VALUES (v_id, 'created', v_actor, jsonb_build_object('slug', v_slug, 'name_source', _name_source));
  RETURN v_id;
END;
$$;
REVOKE ALL ON FUNCTION public.admin_virtual_account_create(text, text, text, text, text, text[], text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_virtual_account_create(text, text, text, text, text, text[], text, text) TO authenticated, service_role;

/**
 * Change a virtual account: its bio, sports, background, notes, whether it's active, whether it
 * likes posts, how many a day and its quiet hours. A name in the patch goes through
 * admin_virtual_account_rename (checked, kept in the activity). A photo can never be set here.
 */
CREATE OR REPLACE FUNCTION public.admin_virtual_account_update(_uid uuid, _patch jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  v_actor uuid := auth.uid();
  va public.virtual_accounts;
  p jsonb := coalesce(_patch, '{}'::jsonb);
  v_first text;
  v_last text;
BEGIN
  IF NOT public.has_role(v_actor, 'admin') THEN RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501'; END IF;
  SELECT * INTO va FROM public.virtual_accounts WHERE user_id = _uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Not a virtual account' USING ERRCODE = '22023'; END IF;
  IF p ? 'first_name' OR p ? 'last_name' THEN
    v_first := CASE WHEN p ? 'first_name' THEN btrim(coalesce(p->>'first_name', '')) ELSE va.first_name END;
    v_last := CASE WHEN p ? 'last_name' THEN nullif(btrim(coalesce(p->>'last_name', '')), '') ELSE va.last_name END;
    IF v_first IS DISTINCT FROM va.first_name OR v_last IS DISTINCT FROM va.last_name THEN
      PERFORM public.admin_virtual_account_rename(_uid, v_first, v_last);
    END IF;
    p := p - 'first_name' - 'last_name';
  END IF;
  UPDATE public.virtual_accounts SET
    background = CASE WHEN p ? 'background' THEN nullif(left(btrim(coalesce(p->>'background', '')), 600), '') ELSE background END,
    notes = CASE WHEN p ? 'notes' THEN nullif(left(btrim(coalesce(p->>'notes', '')), 600), '') ELSE notes END,
    active = CASE WHEN p ? 'active' THEN (p->>'active')::boolean ELSE active END,
    likes_enabled = CASE WHEN p ? 'likes_enabled' THEN (p->>'likes_enabled')::boolean ELSE likes_enabled END,
    daily_like_limit = CASE WHEN p ? 'daily_like_limit' THEN least(greatest((p->>'daily_like_limit')::int, 0), 20) ELSE daily_like_limit END,
    quiet_start = CASE WHEN p ? 'quiet_start' THEN least(greatest((p->>'quiet_start')::int, 0), 23) ELSE quiet_start END,
    quiet_end = CASE WHEN p ? 'quiet_end' THEN least(greatest((p->>'quiet_end')::int, 0), 23) ELSE quiet_end END,
    updated_by = v_actor, updated_at = now()
  WHERE user_id = _uid;
  IF p ? 'bio' OR p ? 'disciplines' THEN
    UPDATE public.community_profiles SET
      bio = CASE WHEN p ? 'bio' THEN nullif(left(btrim(coalesce(p->>'bio', '')), 150), '') ELSE bio END,
      disciplines = CASE WHEN p ? 'disciplines' AND jsonb_typeof(p->'disciplines') = 'array'
                         THEN coalesce(ARRAY(SELECT d FROM jsonb_array_elements_text(p->'disciplines') d
                                              WHERE d IN ('powerlifting', 'bodybuilding', 'strength', 'glutes', 'fitness') LIMIT 3), '{}')
                         ELSE disciplines END,
      avatar_path = NULL,
      updated_at = now()
     WHERE user_id = _uid;
  END IF;
  IF p <> '{}'::jsonb THEN
    INSERT INTO public.virtual_account_activity (user_id, action, actor_user_id, detail)
    VALUES (_uid,
            CASE WHEN p ? 'active' AND (p->>'active')::boolean IS DISTINCT FROM va.active
                   THEN CASE WHEN (p->>'active')::boolean THEN 'activated' ELSE 'deactivated' END
                 WHEN p ? 'likes_enabled' AND (p->>'likes_enabled')::boolean IS DISTINCT FROM va.likes_enabled
                   THEN CASE WHEN (p->>'likes_enabled')::boolean THEN 'likes_on' ELSE 'likes_off' END
                 ELSE 'updated' END,
            v_actor, jsonb_build_object('patch', p));
  END IF;
  SELECT * INTO va FROM public.virtual_accounts WHERE user_id = _uid;
  RETURN to_jsonb(va);
END;
$$;
REVOKE ALL ON FUNCTION public.admin_virtual_account_update(uuid, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_virtual_account_update(uuid, jsonb) TO authenticated;

/** The admin page: every virtual account with its counts, how it got its name, and what's wrong with it now. */
CREATE OR REPLACE FUNCTION public.admin_virtual_accounts()
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
BEGIN
  IF NOT ((SELECT public.has_role(auth.uid(), 'admin')) OR (SELECT public.is_admin_viewer())) THEN
    RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501';
  END IF;
  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'user_id', va.user_id, 'slug', va.slug, 'first_name', va.first_name, 'last_name', va.last_name,
             'background', va.background, 'notes', va.notes, 'active', va.active, 'likes_enabled', va.likes_enabled,
             'daily_like_limit', va.daily_like_limit, 'quiet_start', va.quiet_start, 'quiet_end', va.quiet_end,
             'bio', cp.bio, 'disciplines', to_jsonb(coalesce(cp.disciplines, '{}')), 'username', cp.username,
             'created_at', va.created_at,
             'name_gender', va.name_gender, 'name_origin', va.name_origin, 'name_source', va.name_source,
             'name_set_at', va.name_set_at,
             'name_problem', public.virtual_name_problem(va.first_name, coalesce(va.last_name, ''), va.user_id),
             'likes_24h', (SELECT count(*) FROM public.virtual_account_activity a
                            WHERE a.user_id = va.user_id AND a.action = 'like' AND a.created_at > now() - interval '24 hours'),
             'likes_total', (SELECT count(*) FROM public.community_reactions r WHERE r.user_id = va.user_id),
             'followers', (SELECT count(*) FROM public.community_follows f WHERE f.followee_id = va.user_id),
             'last_like_at', (SELECT max(a.created_at) FROM public.virtual_account_activity a WHERE a.user_id = va.user_id AND a.action = 'like')
           ) ORDER BY va.created_at), '[]'::jsonb)
      FROM public.virtual_accounts va
      LEFT JOIN public.community_profiles cp ON cp.user_id = va.user_id
  );
END;
$$;
REVOKE ALL ON FUNCTION public.admin_virtual_accounts() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_virtual_accounts() TO authenticated;

/* ─────────────────────────── 7. The like tick corrects names first ─────────────────────────── */

/**
 * Every 20 minutes: first any virtual account with a placeholder name gets a real one (whether
 * or not likes are on); then, while the global switch is on, each active virtual account with
 * likes on may like one recent crew-wide post by a real person (never a virtual account's, a
 * story, an automatic workout card, a followers-only or Close Friends post, a post whose author
 * blocked it, or one that already has the most virtual likes a post may get), outside its quiet
 * hours (Winnipeg), at most its daily limit and one an account per 45 minutes, by chance so it
 * doesn't run like a clock. Each like is kept in the activity log; a like is never a notification.
 */
CREATE OR REPLACE FUNCTION public.virtual_accounts_tick()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE
  s jsonb := public.virtual_accounts_settings();
  v record;
  v_hour integer;
  v_post uuid;
  v_n integer := 0;
  v_quiet boolean;
BEGIN
  IF EXISTS (SELECT 1 FROM public.virtual_accounts va WHERE public.virtual_name_placeholder(va.first_name, va.last_name) IS NOT NULL) THEN
    PERFORM public.virtual_accounts_fix_placeholder_names();
  END IF;
  IF NOT (s->>'automation_enabled')::boolean THEN RETURN 0; END IF;
  v_hour := extract(hour FROM public.instant_to_local(now(), 'America/Winnipeg'))::int;
  FOR v IN SELECT * FROM public.virtual_accounts WHERE active AND likes_enabled AND daily_like_limit > 0 ORDER BY random() LOOP
    v_quiet := CASE
      WHEN v.quiet_start = v.quiet_end THEN false
      WHEN v.quiet_start > v.quiet_end THEN v_hour >= v.quiet_start OR v_hour < v.quiet_end
      ELSE v_hour >= v.quiet_start AND v_hour < v.quiet_end END;
    CONTINUE WHEN v_quiet;
    CONTINUE WHEN (SELECT count(*) FROM public.virtual_account_activity a
                    WHERE a.user_id = v.user_id AND a.action = 'like' AND a.actor_user_id IS NULL
                      AND a.created_at > now() - interval '24 hours') >= v.daily_like_limit;
    CONTINUE WHEN EXISTS (SELECT 1 FROM public.virtual_account_activity a
                           WHERE a.user_id = v.user_id AND a.action = 'like' AND a.created_at > now() - interval '45 minutes');
    CONTINUE WHEN random() > least(1.0, v.daily_like_limit::numeric / 40.0);
    SELECT p.id INTO v_post
      FROM public.community_posts p
     WHERE p.archived_at IS NULL
       AND p.visibility = 'community'
       AND NOT coalesce(p.story_only, false)
       AND NOT coalesce(p.auto_shared, false)
       AND p.author_user_id IS NOT NULL
       AND p.created_at > now() - make_interval(hours => (s->>'max_post_age_hours')::int)
       AND p.created_at < now() - make_interval(mins => (s->>'min_post_age_minutes')::int)
       AND NOT EXISTS (SELECT 1 FROM public.virtual_accounts va WHERE va.user_id = p.author_user_id)
       AND ((s->>'include_coach_posts')::boolean
            OR (p.series IS NULL AND p.author_user_id NOT IN (SELECT x FROM public.community_staff_people() x WHERE x IS NOT NULL)))
       AND NOT EXISTS (SELECT 1 FROM public.community_reactions r WHERE r.post_id = p.id AND r.user_id = v.user_id)
       AND (SELECT count(*) FROM public.community_reactions r JOIN public.virtual_accounts va ON va.user_id = r.user_id
             WHERE r.post_id = p.id) < (s->>'per_post_max')::int
       AND NOT public.chat_has_blocked(p.author_user_id, v.user_id)
     ORDER BY random()
     LIMIT 1;
    CONTINUE WHEN v_post IS NULL;
    INSERT INTO public.community_reactions (post_id, user_id, emoji) VALUES (v_post, v.user_id, 'heart')
    ON CONFLICT DO NOTHING;
    IF FOUND THEN
      INSERT INTO public.virtual_account_activity (user_id, action, post_id, detail)
      VALUES (v.user_id, 'like', v_post, '{"by":"automation"}'::jsonb);
      v_n := v_n + 1;
    END IF;
  END LOOP;
  RETURN v_n;
END;
$$;
REVOKE ALL ON FUNCTION public.virtual_accounts_tick() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.virtual_accounts_tick() TO service_role;

/* ─────────────────────────── 8. The accounts there now ─────────────────────────── */

-- What the existing accounts' names are made of, read from the pool; the starters say so.
UPDATE public.virtual_accounts v SET
  name_gender = coalesce(v.name_gender, public.virtual_name_gender_of(v.first_name)),
  name_origin = coalesce(v.name_origin, public.virtual_name_origin_of(v.last_name)),
  name_source = coalesce(v.name_source, CASE WHEN v.slug = ANY(ARRAY['maya.lifts', 'theo.trains', 'priya.strong', 'diego.pulls', 'hannah.reps', 'kofi.benches', 'ellie.moves', 'sam.at.home', 'aiyana.squats', 'graham.masters', 'lena.builds', 'jordan.newbie']::text[]) THEN 'starter' ELSE 'admin' END),
  name_set_at = coalesce(v.name_set_at, v.created_at);
ALTER TABLE public.virtual_accounts ALTER COLUMN name_source SET DEFAULT 'admin';
ALTER TABLE public.virtual_accounts ALTER COLUMN name_set_at SET DEFAULT now();

-- Any placeholder name there now gets a real one, keeping the account and everything on it.
SELECT public.virtual_accounts_fix_placeholder_names();
